-- Netherstorm: creature abilities
-- Most of the zone's creatures (the Sunfury blood elves, the Burning Legion, the ethereals, the mana creatures and wildlife) had no
-- AI or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows
-- needing events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The
-- creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '18850,18853,18855,18858,18870,19466,19467,19541,19554,19692,19705,19940,20102,20132,20134,20139,20202,20248,20340,20394,20397,20402,20403,20404,20409,20416,20435,20452,20453,20454,20456,20458,20459,20483,20512,20516,20554,20607,20611,20634,20673,20685,20727,20769,20770,20773,20775,20779,20794,20800,20801,20803,20854,20928,20929,20930,20931,20932,20984,21065,21089,21135,21805,21923,21925,22822,23008';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '20335,20447,20484,20485,20606,20983,21783,22408,22494,22821';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
